          <div style="display:grid;grid-template-columns:1.4fr .8fr .7fr;padding:5px 7px;background:var(--card-bg);color:var(--card-fg-muted);"><span>고객</span><span>상태</span><span>금액</span></div>
          <div style="display:grid;grid-template-columns:1.4fr .8fr .7fr;padding:5px 7px;border-top:1px solid var(--card-border);align-items:center;"><b>Acme Inc.</b><span style="color:#6ABE39;">● 완료</span><span>¥8,240</span></div>
          <div style="display:grid;grid-template-columns:1.4fr .8fr .7fr;padding:5px 7px;border-top:1px solid var(--card-border);align-items:center;"><b>Globex</b><span style="color:var(--card-accent);">● 진행</span><span>¥5,120</span></div>
